\title{A Sharp Dichotomy for the Total $d$-Hoggatt Numbers}
\author{Aristotle}
\date{2026-07-13}

\begin{document}

\begin{abstract}
The \emph{total} $d$-Hoggatt numbers are the row sums $H_d(n)=\sum_k H_d(n,k)$ of the $d$-Hoggatt triangle. Classical identifications give $H_1(n)=2^n$ (row sums of Pascal's triangle), $H_2(n)=C_n$ (the Catalan numbers), and $H_3(n)$ (the Baxter numbers). We establish a sharp dichotomy between the first two levels of this hierarchy. The $d=1$ totals $2^n$ are \emph{log-linear} --- they satisfy $H(n+1)^2=H(n)H(n+2)$ with exact equality --- and are therefore log-concave, log-convex, and, decisively, \emph{not} strictly log-convex. The $d=2$ totals $C_n$ are \emph{strictly log-convex} --- $H(n+1)^2<H(n)H(n+2)$ for all $n$ --- and are therefore \emph{not} log-concave. The engine of the Catalan case is an exact discriminant identity $(2n+1)(n+3)\,C_nC_{n+2}=(n+2)(2n+3)\,C_{n+1}^2$, whose two coefficients differ by the positive constant $3$. We isolate the general mechanism as a ratio-monotonicity criterion over the reals, and record the tropical (dequantized) reformulation: strict log-convexity is exactly strict convexity of the logarithm, equivalently strict concavity of the valuation $v=-\log a$. We close with five conjectures extending the dichotomy across the whole hierarchy.
\end{abstract}

\maketitle

\section{Introduction}

Curvature properties of positive integer sequences --- log-concavity, log-linearity, and log-convexity --- are among the most studied structural features in enumerative combinatorics. Log-concave sequences are unimodal, behave well under convolution, and frequently arise as coefficient sequences of real-rooted polynomials; log-convex sequences signal accelerating, super-multiplicative growth. Determining precisely which behavior a natural counting family exhibits, and where in a parametrized family the behavior \emph{switches}, is a recurring theme.

This paper concerns the $d$-Hoggatt triangles, a hierarchy indexed by $d=1,2,3,\dots$ whose row-sum sequences $H_d(n)=\sum_k H_d(n,k)$ specialize to three classical objects:
\begin{itemize}
  \item $d=1$: $H_1(n)=2^n$, the row sums of Pascal's triangle;
  \item $d=2$: $H_2(n)=C_n$, the Catalan numbers;
  \item $d=3$: $H_3(n)$, the Baxter numbers.
\end{itemize}
Our main contribution is a sharp dichotomy between the first two levels: the powers of two sit exactly on the boundary between log-concavity and log-convexity (they are log-linear), whereas the Catalan totals fall strictly on the log-convex side. The transition from $d=1$ to $d=2$ is therefore as sharp as possible --- an equality becomes a strict inequality --- with no intermediate regime.

\section{Definitions}

Throughout, $a:\mathbb{N}\to\mathbb{N}$ (or $\mathbb{R}$) denotes a nonnegative sequence.

\begin{definition}[Strict log-convexity]
$a$ is \emph{strictly log-convex} if $a(n+1)^2<a(n)\,a(n+2)$ for all $n$.
\end{definition}

\begin{definition}[Log-concavity]
$a$ is \emph{log-concave} if $a(n)\,a(n+2)\le a(n+1)^2$ for all $n$.
\end{definition}

\begin{definition}[Log-linearity]
$a$ is \emph{log-linear} if $a(n+1)^2=a(n)\,a(n+2)$ for all $n$.
\end{definition}

These conditions say exactly that $n\mapsto\log a(n)$ is convex, concave, or affine, respectively (when $a>0$).

\begin{lemma}\label{lem:linconc}
A log-linear sequence is log-concave.
\end{lemma}
\begin{proof}
If $a(n+1)^2=a(n)a(n+2)$ then $a(n)a(n+2)\le a(n+1)^2$, the log-concavity inequality.
\end{proof}

\begin{lemma}\label{lem:notconc}
A strictly log-convex sequence is not log-concave.
\end{lemma}
\begin{proof}
If $a$ were both, then at $n=0$ we would have $a(1)^2<a(0)a(2)\le a(1)^2$, a contradiction.
\end{proof}

\section{The case $d=1$: the totals $2^n$ are log-linear}

\begin{theorem}[Log-linearity of the powers of two]\label{thm:pow}
The sequence $H_1(n)=2^n$ satisfies $\left(2^{\,n+1}\right)^2=2^n\cdot 2^{\,n+2}$ for all $n$.
\end{theorem}
\begin{proof}
Both sides equal $2^{2n+2}$.
\end{proof}

\begin{corollary}
$2^n$ is log-concave. (Immediate from Lemma~\ref{lem:linconc}.)
\end{corollary}

\begin{theorem}\label{thm:pownotconv}
The sequence $2^n$ is not strictly log-convex.
\end{theorem}
\begin{proof}
Strict log-convexity at $n=0$ would require $(2^1)^2<2^0\cdot 2^2$, i.e. $4<4$, which is false.
\end{proof}

\section{The case $d=2$: the Catalan totals}

We write $C_n=\binom{2n}{n}/(n+1)$ for the $n$-th Catalan number.

\begin{proposition}[Positivity]\label{prop:pos}
$C_n>0$ for all $n$.
\end{proposition}
\begin{proof}
$\binom{2n}{n}>0$ and $(n+1)\mid\binom{2n}{n}$, so $C_n$ is a positive integer.
\end{proof}

\begin{proposition}[Multiplicative recurrence]\label{prop:rec}
For all $n$, $(n+2)\,C_{n+1}=2(2n+1)\,C_n$.
\end{proposition}
\begin{proof}
This is the classical two-term recurrence, equivalent to $\binom{2(n+1)}{n+1}=\frac{2(2n+1)}{n+1}\binom{2n}{n}$ together with $C_n=\binom{2n}{n}/(n+1)$.
\end{proof}

The recurrence gives the growth ratio $C_{n+1}/C_n=2(2n+1)/(n+2)$, strictly increasing to $4$.

\begin{theorem}[Discriminant identity]\label{thm:disc}
For all $n$,
\[
(2n+1)(n+3)\,\big(C_n\,C_{n+2}\big)=(n+2)(2n+3)\,C_{n+1}^2.
\]
\end{theorem}
\begin{proof}
Apply Proposition~\ref{prop:rec} twice: $(n+2)C_{n+1}=2(2n+1)C_n$ and $(n+3)C_{n+2}=2(2n+3)C_{n+1}$. Solving for $C_n$ and $C_{n+2}$ and substituting reduces both sides to the same monomial in $C_{n+1}^2$ times integer polynomials in $n$.
\end{proof}

The two coefficients are $(n+2)(2n+3)=2n^2+7n+6$ and $(2n+1)(n+3)=2n^2+7n+3$; they differ by the constant $3>0$, which forces strictness.

\begin{theorem}[Strict log-convexity of the Catalan totals]\label{thm:cataconv}
For all $n$, $C_{n+1}^2<C_n\,C_{n+2}$.
\end{theorem}
\begin{proof}
Write $A=(2n+1)(n+3)>0$ and $B=(n+2)(2n+3)=A+3$. Theorem~\ref{thm:disc} gives $A\,C_nC_{n+2}=(A+3)C_{n+1}^2$, hence $A\big(C_nC_{n+2}-C_{n+1}^2\big)=3\,C_{n+1}^2>0$ by Proposition~\ref{prop:pos}. Since $A>0$, we get $C_nC_{n+2}>C_{n+1}^2$.
\end{proof}

\begin{corollary}
The Catalan totals $C_n$ are not log-concave. (From Theorem~\ref{thm:cataconv} and Lemma~\ref{lem:notconc}.)
\end{corollary}

\section{The sharp dichotomy}

\begin{theorem}[Sharp dichotomy, $d=1$ vs $d=2$]
The sequence $2^n$ is log-linear and not strictly log-convex, while the sequence $C_n$ is strictly log-convex and not log-concave.
\end{theorem}
\begin{proof}
Combine Theorems~\ref{thm:pow}, \ref{thm:pownotconv}, \ref{thm:cataconv} and the preceding corollary.
\end{proof}

The dichotomy is sharp: the boundary case ($d=1$) attains equality in the defining inequality, while the next case ($d=2$) attains strict inequality in the opposite direction, with no intermediate regime.

\section{The general mechanism: ratio monotonicity}

\begin{theorem}[Ratio-monotonicity criterion]\label{thm:ratio}
Let $a:\mathbb{N}\to\mathbb{R}$ be positive. If $\dfrac{a(n+1)}{a(n)}<\dfrac{a(n+2)}{a(n+1)}$ for all $n$, then $a$ is strictly log-convex.
\end{theorem}
\begin{proof}
Fix $n$ and multiply the hypothesis by the positive quantity $a(n)a(n+1)$; clearing denominators yields $a(n+1)^2<a(n)a(n+2)$.
\end{proof}

\begin{theorem}[Catalan ratios are strictly increasing]
For all $n$, $\dfrac{C_{n+1}}{C_n}<\dfrac{C_{n+2}}{C_{n+1}}$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:cataconv}, $C_{n+1}^2<C_nC_{n+2}$; divide by $C_nC_{n+1}>0$. This exhibits the Catalan case as the instance $a=C$ of Theorem~\ref{thm:ratio}.
\end{proof}

Conceptually: the rows of these triangles are log-concave, but the row ratios $T(n+1,k)/T(n,k)$ are nondecreasing in $n$, and summation amplifies that common growth factor --- a Chebyshev-sum / rearrangement effect.

\section{Tropical dequantization}

\begin{theorem}[Log form of strict log-convexity]\label{thm:log}
Let $a:\mathbb{N}\to\mathbb{R}$ be positive. Then for each $n$,
\[
a(n+1)^2<a(n)\,a(n+2)\iff 2\log a(n+1)<\log a(n)+\log a(n+2).
\]
\end{theorem}
\begin{proof}
Since $a>0$, $\log$ is strictly monotone; take $\log$ of both sides and use $\log(xy)=\log x+\log y$ and $\log(x^2)=2\log x$.
\end{proof}

With the valuation $v(n)=-\log a(n)$, strict log-convexity of $a$ is strict concavity of $v$, and log-linearity of $a$ is affinity of $v$. The test degenerates to the sign of the second finite difference $\Delta^2 v(n)=v(n)-2v(n+1)+v(n+2)$: for $d=1$, $\Delta^2 v\equiv 0$; for $d=2$, $\Delta^2 v<0$.

\section{Applications}

Log-concavity of a coefficient sequence forces unimodality, and the log-linearity of $2^n$ marks the exact edge of this behavior. Strict log-convexity of $C_n$ certifies that the ratios $C_{n+1}/C_n$ increase monotonically to $4$, giving rigorous growth-rate bounds. Log-concave/log-convex dichotomies underpin correlation inequalities, entropy comparisons, and partition-function estimates; the jump from a coefficient gap of $0$ to a gap of $3$ is a clean model for where such inequalities flip. Finally, Theorem~\ref{thm:ratio} is a reusable certificate: to prove log-convexity it suffices to check that consecutive ratios increase.

\section{Discussion and future directions}

\begin{conjecture}[Universal log-convexity of the totals for $d\ge 2$]
For every $d\ge2$, $H_d(n+1)^2<H_d(n)H_d(n+2)$ for all $n$. Each $H_d(n)$ is a positively weighted sum of products of binomial coefficients whose dominant growth ratio increases with $n$; a uniform proof would come from a $d$-independent two-term recurrence yielding a discriminant identity with a positive coefficient gap, generalizing Theorem~\ref{thm:disc}. The Baxter case ($d=3$) matches the Catalan case term-by-term in computation.
\end{conjecture}

\begin{conjecture}[Row-sum log-convexity as a summation phenomenon]
If $T(n,k)$ is any triangle whose rows are log-concave and whose row-ratio $T(n+1,k)/T(n,k)$ is nondecreasing in $n$, then the row sums $S(n)=\sum_k T(n,k)$ are log-convex.
\end{conjecture}

\begin{conjecture}[Infinite log-concavity of the rows]
For every $d\ge1$, each fixed row $k\mapsto H_d(n,k)$ is infinitely log-concave, via a closure lemma with the golden-ratio-squared safety factor $a_k^2\ge\frac{3+\sqrt5}{2}\,a_{k-1}a_{k+1}$, the fixed point of the operator's worst-case ratio.
\end{conjecture}

\begin{conjecture}[Log-concave renormalization of the totals]
For every $d\ge2$ there is an explicit positive $w_d(n)$ (e.g. a ratio of factorials) such that $H_d(n)/w_d(n)$ is infinitely log-concave. The Catalan growth ratio $\frac{(n+2)(2n+3)}{(2n+1)(n+3)}$ is the concrete candidate for $w_2$.
\end{conjecture}

\begin{conjecture}[Tropical dequantization]
Under $v_n=-\log a_n$, log-concavity becomes convexity of $v$ and log-linearity becomes affinity. The dichotomy reads: $v$ affine for $d=1$, strictly concave for $d\ge2$; infinite log-concavity corresponds to iterated finite differences retaining a fixed sign.
\end{conjecture}

\section{Conclusion}

We proved a sharp dichotomy at the foot of the $d$-Hoggatt hierarchy: the $d=1$ totals $2^n$ are log-linear and never strictly log-convex, while the $d=2$ totals $C_n$ are strictly log-convex and never log-concave. The proof rests on an exact discriminant identity whose two coefficients differ by the constant $3$, generalizes to a ratio-monotonicity mechanism, and admits a tropical reformulation, laying the groundwork for a uniform theory of curvature across the hierarchy.

