"""Curvature census of the total d-Hoggatt numbers (d = 1, 2, 3)."""
from __future__ import annotations
import math
from typing import Callable

def pow_two(n: int) -> int:
    return 1 << n

def catalan(n: int) -> int:
    return math.comb(2 * n, n) // (n + 1)

def baxter(n: int) -> int:
    if n == 0:
        return 1
    denom = math.comb(n + 1, 1) * math.comb(n + 1, 2)
    total = sum(
        math.comb(n + 1, k - 1) * math.comb(n + 1, k) * math.comb(n + 1, k + 1)
        for k in range(1, n + 1)
    )
    return total // denom

def discriminant(a: Callable[[int], int], n: int) -> int:
    """a(n)*a(n+2) - a(n+1)^2 :  >0 log-convex, =0 log-linear, <0 log-concave."""
    return a(n) * a(n + 2) - a(n + 1) ** 2

def census(a: Callable[[int], int], upto: int = 12) -> list[int]:
    return [discriminant(a, n) for n in range(upto)]

if __name__ == "__main__":
    print("2^n     :", census(pow_two))    # all zero  -> log-linear
    print("Catalan :", census(catalan))    # all > 0   -> strictly log-convex
    print("Baxter  :", census(baxter))     # all > 0   -> strictly log-convex (empirical)

"""Verification of the exact Catalan discriminant identity and its constant gap 3."""
from __future__ import annotations
import math

def catalan(n: int) -> int:
    return math.comb(2 * n, n) // (n + 1)

def check_identity(upto: int = 30) -> bool:
    """(2n+1)(n+3) C_n C_{n+2} = (n+2)(2n+3) C_{n+1}^2 for all n < upto."""
    for n in range(upto):
        lhs = (2 * n + 1) * (n + 3) * catalan(n) * catalan(n + 2)
        rhs = (n + 2) * (2 * n + 3) * catalan(n + 1) ** 2
        if lhs != rhs:
            return False
    return True

def coefficient_gap(n: int) -> int:
    """(n+2)(2n+3) - (2n+1)(n+3) -- provably the constant 3."""
    return (n + 2) * (2 * n + 3) - (2 * n + 1) * (n + 3)

if __name__ == "__main__":
    assert check_identity(), "identity failed"
    gaps = {coefficient_gap(n) for n in range(100)}
    print("identity holds for n < 30:", check_identity())
    print("set of coefficient gaps over n < 100:", gaps)  # -> {3}

"""Tropical dequantization: second difference of the valuation v(n) = -log a(n)."""
from __future__ import annotations
import math
from typing import Callable

def pow_two(n: int) -> int:
    return 1 << n

def catalan(n: int) -> int:
    return math.comb(2 * n, n) // (n + 1)

def second_difference_of_valuation(a: Callable[[int], int], n: int) -> float:
    """Delta^2 v(n) = v(n) - 2 v(n+1) + v(n+2), where v(m) = -log a(m).

    == 0  : v affine       (log-linear a)
    >  0  : v strictly concave (strictly log-convex a)
    """
    v = lambda m: -math.log(a(m))
    return v(n) - 2 * v(n + 1) + v(n + 2)

if __name__ == "__main__":
    for n in range(8):
        d1 = second_difference_of_valuation(pow_two, n)
        d2 = second_difference_of_valuation(catalan, n)
        print(f"n={n}:  2^n -> {d1:+.6f}   C_n -> {d2:+.6f}")
    # 2^n gives 0 (affine v); C_n gives strictly positive (strictly concave v)

